INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('a3e107ce-227c-4ca8-a22d-dd9157c5c8eb', 'EX01', 'Goblet squat', 'squat', 'legs', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Pegang dumbbell di depan dada, kaki selebar bahu, dada tegak. Turun terkontrol hingga paha sejajar lantai lalu dorong melalui tumit. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('92973df0-0770-41b8-83bc-0b99b3d1d344', 'EX02', 'Leg press', 'squat', 'legs', 'gym', 1, 2, 3, 8, 12, 'reps', 90, 'Duduk dengan punggung menempel penuh pada sandaran dan kaki selebar bahu di papan. Turunkan beban hingga lutut membentuk sekitar 90 derajat tanpa mengangkat pinggul, lalu dorong kembali tanpa mengunci lutut. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('c2193d14-2ca3-4553-8675-bff9529919d7', 'EX03', 'Bodyweight squat', 'squat', 'legs', 'bodyweight', 1, 3, 3, 10, 15, 'reps', 60, 'Berdiri kaki selebar bahu, kencangkan perut, dan jaga punggung netral. Turunkan pinggul seperti hendak duduk lalu berdiri kembali dengan stabil. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('769b5d98-0342-4c21-8e6c-b46d60d36f1f', 'EX04', 'Barbell back squat', 'squat', 'legs', 'gym', 2, 4, 3, 6, 10, 'reps', 120, 'Letakkan bar di punggung atas, kencangkan inti tubuh, dan tarik napas sebelum turun. Turun terkontrol dengan lutut searah ujung kaki lalu dorong naik secara seimbang. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('bee5eded-2219-49eb-bd80-be36d72c551d', 'EX05', 'Dumbbell Romanian deadlift', 'hinge', 'hamstrings', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Pegang dumbbell di depan paha, lutut sedikit ditekuk, punggung rata. Dorong pinggul ke belakang hingga terasa regangan di paha belakang lalu kembali berdiri dengan mengencangkan glutes. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('516c638a-fa01-43cd-a12c-55b0c262cd45', 'EX06', 'Barbell Romanian deadlift', 'hinge', 'hamstrings', 'gym', 2, 2, 3, 6, 10, 'reps', 120, 'Pegang bar selebar bahu dekat paha dan jaga tulang belakang netral. Engselkan pinggul ke belakang secara terkontrol lalu dorong pinggul maju untuk kembali berdiri. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('559410ca-5360-4ddc-b23c-e32f068a8cec', 'EX07', 'Glute bridge', 'hinge', 'glutes', 'bodyweight', 1, 3, 3, 10, 15, 'reps', 60, 'Berbaring telentang dengan lutut ditekuk dan telapak kaki menapak lantai. Angkat pinggul hingga tubuh membentuk garis lurus dari bahu ke lutut, tahan sejenak, lalu turunkan perlahan. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9f4f08b6-a9a9-43c5-9b70-f4e3a24937b4', 'EX08', 'Dumbbell split squat', 'lunge', 'legs', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Berdiri posisi langkah memanjang sambil memegang dumbbell di samping tubuh. Turunkan lutut belakang mendekati lantai dengan batang tubuh tegak lalu dorong naik melalui kaki depan. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('87b52e7c-d02e-4219-a8d2-c574fdab049f', 'EX09', 'Reverse lunge', 'lunge', 'legs', 'bodyweight', 1, 2, 3, 8, 12, 'reps', 60, 'Langkahkan satu kaki ke belakang dan turunkan tubuh hingga kedua lutut sekitar 90 derajat. Dorong melalui kaki depan untuk kembali ke posisi berdiri dengan seimbang. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('98d3fdff-71f5-4c4b-9676-eff25731eae4', 'EX10', 'Dumbbell bench press', 'horizontal_push', 'chest', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Berbaring di bangku datar dengan kaki menapak kuat dan belikat ditarik rapat. Turunkan dumbbell ke samping dada dengan siku sekitar 45 derajat lalu dorong ke atas terkontrol. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('68a1e2e9-6afc-43f9-9e97-5d05158495d0', 'EX11', 'Machine chest press', 'horizontal_push', 'chest', 'gym', 1, 2, 3, 8, 12, 'reps', 90, 'Atur tinggi kursi sehingga pegangan sejajar tengah dada dan punggung menempel. Dorong pegangan ke depan tanpa mengunci siku lalu kembalikan perlahan. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('d5fdd80d-0df3-4f8f-87b1-6613b4ab1149', 'EX12', 'Incline push-up', 'horizontal_push', 'chest', 'bodyweight', 1, 3, 3, 8, 15, 'reps', 60, 'Letakkan tangan pada permukaan lebih tinggi seperti bangku dengan tubuh lurus dari kepala hingga tumit. Turunkan dada mendekati tumpuan lalu dorong kembali sambil menjaga inti kencang. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('845e3dd2-5fe0-4db0-8e8e-fad146a0b38f', 'EX13', 'Push-up', 'horizontal_push', 'chest', 'bodyweight', 2, 4, 3, 6, 15, 'reps', 60, 'Posisikan tangan sedikit lebih lebar dari bahu dan tubuh lurus seperti papan. Turunkan dada mendekati lantai dengan siku sekitar 45 derajat lalu dorong naik. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('f865a173-5391-4ed7-b9f2-0447cf14fad3', 'EX14', 'One-arm dumbbell row', 'horizontal_pull', 'back', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Tumpukan satu tangan dan lutut di bangku dengan punggung rata sejajar lantai. Tarik dumbbell ke arah pinggul sambil merapatkan belikat lalu turunkan terkontrol. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('3ec201cf-e452-4993-9caa-64121fbf5666', 'EX15', 'Seated cable row', 'horizontal_pull', 'back', 'gym', 1, 2, 3, 8, 12, 'reps', 90, 'Duduk tegak dengan lutut sedikit ditekuk dan dada terangkat. Tarik pegangan ke arah perut bawah dengan merapatkan belikat tanpa mengayunkan punggung. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('922ffd7d-e90d-4779-b39a-598be872d9dc', 'EX16', 'Prone Y-T raise', 'horizontal_pull', 'back', 'bodyweight', 1, 5, 3, 10, 15, 'reps', 60, 'Berbaring telungkup di matras dengan dahi disangga ringan. Angkat lengan membentuk huruf Y lalu T menggunakan otot punggung atas secara perlahan. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('450932dc-cb56-4526-bedf-06c2311ab30e', 'EX17', 'Dumbbell shoulder press', 'vertical_push', 'shoulders', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Duduk atau berdiri tegak dengan inti kencang dan dumbbell setinggi bahu. Dorong dumbbell ke atas kepala tanpa melengkungkan punggung bawah lalu turunkan perlahan. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('dba246a0-28b5-458e-813a-c4de6478293e', 'EX18', 'Machine shoulder press', 'vertical_push', 'shoulders', 'gym', 1, 2, 3, 8, 12, 'reps', 90, 'Duduk dengan punggung menempel pada sandaran dan pegang handel setinggi bahu. Dorong ke atas secara terkontrol lalu turunkan kembali tanpa membanting beban. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('ea6a3a9c-7f9e-4a3a-9bc6-bd69c2326fdc', 'EX19', 'Pike push-up', 'vertical_push', 'shoulders', 'bodyweight', 2, 3, 3, 6, 12, 'reps', 60, 'Bentuk posisi huruf V terbalik dengan pinggul tinggi dan tangan menapak kuat. Tekuk siku untuk menurunkan puncak kepala mendekati lantai lalu dorong kembali. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9ea6ad62-7bf7-482e-b0f2-24ebd425909b', 'EX20', 'Lat pulldown', 'vertical_pull', 'back', 'gym', 1, 1, 3, 8, 12, 'reps', 90, 'Duduk tegak, pegang bar sedikit lebih lebar dari bahu, dan condongkan dada sedikit. Tarik bar ke dada atas dengan mengaktifkan punggung lalu kembalikan perlahan. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('717d1cb5-10fc-479f-8607-7b7fb6f3f185', 'EX21', 'Assisted pull-up', 'vertical_pull', 'back', 'gym', 2, 2, 3, 5, 10, 'reps', 90, 'Gunakan mesin bantuan pull-up dengan pegangan selebar bahu. Tarik tubuh hingga dagu melewati palang sambil menjaga inti tetap stabil lalu turun terkontrol. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('158ac696-cdbb-4560-86ea-c40e501eb49b', 'EX22', 'Plank', 'core', 'core', 'bodyweight', 1, 1, 3, 20, 40, 'seconds', 45, 'Bertumpu pada lengan bawah dan ujung kaki dengan tubuh lurus dari kepala hingga tumit. Kencangkan perut dan glutes sambil bernapas teratur tanpa menurunkan pinggul. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('fa5e339c-f7e5-49f3-8d81-0012c9830b8d', 'EX23', 'Dead bug', 'core', 'core', 'bodyweight', 1, 2, 3, 8, 12, 'reps', 45, 'Berbaring telentang dengan punggung bawah menempel lantai, lengan ke atas, dan lutut 90 derajat. Luruskan lengan dan kaki berlawanan secara perlahan lalu kembali bergantian. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('69685290-b391-4c55-9b35-de6f4d04403f', 'EX24', 'Side plank', 'core', 'core', 'bodyweight', 1, 3, 2, 15, 30, 'seconds', 45, 'Bertumpu pada satu lengan bawah di samping tubuh dengan kaki ditumpuk dan pinggul terangkat. Jaga garis lurus tubuh pada setiap sisi selama waktu yang ditentukan. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('ae63b769-23da-422e-97a1-6ba5771268eb', 'EX25', 'Farmer''s carry', 'carry', 'full_body', 'dumbbell', 1, 1, 3, 20, 40, 'seconds', 60, 'Pegang sepasang dumbbell di samping tubuh, tarik bahu ke belakang, dan kencangkan inti. Berjalan dengan langkah pendek dan stabil selama durasi set. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('daebcb1f-9bdb-40a7-bb31-6c92bd21e395', 'EX26', 'Barbell bench press', 'horizontal_push', 'chest', 'gym', 2, 10, 4, 6, 10, 'reps', 120, 'Berbaring di bench datar, kaki menapak kuat, genggam bar sedikit lebih lebar dari bahu. Turunkan bar terkontrol ke tengah dada lalu dorong kembali ke atas tanpa mengangkat pinggul. Gunakan pengaman atau spotter untuk beban berat.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('e9948a61-9bd8-4416-8803-5c6d76850d49', 'EX27', 'Incline barbell bench press', 'horizontal_push', 'chest', 'gym', 2, 11, 3, 6, 10, 'reps', 120, 'Atur bench miring 30–45 derajat, genggam bar sedikit lebih lebar dari bahu. Turunkan bar ke dada atas secara stabil lalu dorong ke atas dengan bahu tetap tertarik ke belakang.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6d141a50-2c5a-479d-ad68-39b724dbd813', 'EX28', 'Decline barbell bench press', 'horizontal_push', 'chest', 'gym', 2, 12, 3, 8, 12, 'reps', 90, 'Kunci kaki di decline bench, turunkan bar perlahan ke area dada bawah lalu dorong kembali secara terkontrol sambil menjaga pergelangan tangan lurus.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('d862c224-a62a-4219-89b0-87d8ea2861fc', 'EX29', 'Smith machine bench press', 'horizontal_push', 'chest', 'gym', 1, 13, 3, 8, 12, 'reps', 90, 'Posisikan bench datar sejajar rel Smith machine agar bar turun tepat di tengah dada. Lepas kait, turunkan perlahan, lalu dorong kembali tanpa mengunci siku.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('f46e7a4d-933b-44fb-8db7-d46366349f8c', 'EX30', 'Incline machine chest press', 'horizontal_push', 'chest', 'gym', 1, 14, 3, 8, 12, 'reps', 90, 'Atur kursi agar pegangan sejajar dada atas. Dorong pegangan maju secara terkontrol untuk melatih dada bagian atas lalu kembalikan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('98acf53b-7ec3-4d39-a289-5a82cf807133', 'EX31', 'Pec deck fly', 'horizontal_push', 'chest', 'gym', 1, 15, 3, 10, 15, 'reps', 60, 'Duduk tegak menempel sandaran dengan siku sedikit ditekuk pada bantalan atau pegangan. Rapatkan kedua lengan di depan dada sambil meremas otot dada lalu buka kembali perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('13387d9a-f4aa-4fc1-bee1-223a746d62c0', 'EX32', 'Cable crossover', 'horizontal_push', 'chest', 'gym', 1, 16, 3, 10, 15, 'reps', 60, 'Berdiri di tengah mesin kabel dengan puli tinggi, condongkan tubuh sedikit ke depan. Tarik kedua pegangan menyilang atau bertemu di depan dada bawah dengan siku sedikit ditekuk.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('1ed6e552-1474-46d0-931b-46dfbb7e8fcd', 'EX33', 'Low-to-high cable fly', 'horizontal_push', 'chest', 'gym', 1, 17, 3, 10, 15, 'reps', 60, 'Atur puli kabel di posisi bawah, pegang handel dengan telapak menghadap depan. Angkat kedua lengan menyatu ke depan dada atas secara terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('42550171-82ac-4eb2-89b7-06b1119e9905', 'EX34', 'Assisted chest dips', 'horizontal_push', 'chest', 'gym', 1, 18, 3, 8, 12, 'reps', 90, 'Gunakan mesin bantuan dips, condongkan tubuh sedikit ke depan dengan siku agak melebar. Turunkan tubuh hingga bahu sejajar siku lalu dorong naik kembali.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5fe0c685-80ee-48ee-9d9e-2a8e48b5e71c', 'EX35', 'Weighted chest dips', 'horizontal_push', 'chest', 'gym', 2, 19, 3, 6, 10, 'reps', 120, 'Gunakan dip belt atau beban tambahan di antara kaki, condongkan badan ke depan di parallel bar. Turun terkontrol hingga terasa regangan dada lalu dorong kembali ke atas.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5846d1aa-fe33-4f7a-862a-2aafa7f90c1f', 'EX36', 'Incline dumbbell bench press', 'horizontal_push', 'chest', 'dumbbell', 1, 20, 3, 8, 12, 'reps', 90, 'Berbaring pada bench miring 30 derajat sambil memegang dumbbell di samping dada atas. Dorong dumbbell ke atas hingga hampir bertemu lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('b8a14e63-899e-4719-96af-add5548b2454', 'EX37', 'Decline dumbbell bench press', 'horizontal_push', 'chest', 'dumbbell', 2, 21, 3, 8, 12, 'reps', 90, 'Berbaring di decline bench dengan kaki terkunci, pegang dumbbell di samping dada bawah. Dorong ke atas dengan jalur stabil lalu turunkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('4032ae80-73ef-4c44-8933-c1f3146630cf', 'EX38', 'Dumbbell chest fly', 'horizontal_push', 'chest', 'dumbbell', 1, 22, 3, 10, 15, 'reps', 60, 'Berbaring di bench datar, angkat dumbbell di atas dada dengan siku sedikit ditekuk. Buka lengan melebar hingga terasa regangan dada lalu rapatkan kembali seperti memeluk.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('e353ebf8-510e-48ad-9246-229960058164', 'EX39', 'Dumbbell floor press', 'horizontal_push', 'chest', 'dumbbell', 1, 23, 3, 8, 12, 'reps', 75, 'Berbaring di lantai dengan lutut ditekuk dan dumbbell di tangan. Turunkan siku hingga menyentuh lantai sejenak lalu dorong dumbbell kembali ke atas.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('46c455c6-0bde-4a59-bc84-3cd0dec70095', 'EX40', 'Dumbbell pullover', 'horizontal_push', 'chest', 'dumbbell', 2, 24, 3, 10, 12, 'reps', 75, 'Berbaring melintang atau sejajar bench sambil memegang satu dumbbell dengan kedua tangan di atas dada. Ayunkan perlahan ke belakang kepala dengan siku sedikit ditekuk lalu tarik kembali.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('8d036052-0b21-4ab2-9e62-2a51eca641ee', 'EX41', 'Knee push-up', 'horizontal_push', 'chest', 'bodyweight', 1, 25, 3, 10, 15, 'reps', 60, 'Bertumpu pada lutut dan telapak tangan dengan tubuh lurus dari kepala hingga lutut. Turunkan dada mendekati lantai lalu dorong kembali dengan perut tetap kencang.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('1f97af1c-f508-4d0f-bf02-79615d9e54ca', 'EX42', 'Decline push-up', 'horizontal_push', 'chest', 'bodyweight', 2, 26, 3, 8, 15, 'reps', 60, 'Letakkan kedua kaki di atas bangku atau permukaan lebih tinggi dan tangan di lantai. Turunkan dada mendekati lantai untuk fokus dada atas dan bahu lalu dorong naik.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('60b48106-0a14-4cb6-8a45-667b4d420e8a', 'EX43', 'Wide-grip push-up', 'horizontal_push', 'chest', 'bodyweight', 1, 27, 3, 8, 15, 'reps', 60, 'Posisikan tangan lebih lebar dari bahu dengan tubuh lurus. Turunkan dada terkontrol hingga mendekati lantai lalu dorong kembali dengan meremas otot dada.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('435b09c2-6706-46cb-bfa4-d396329384e3', 'EX44', 'Diamond push-up', 'horizontal_push', 'chest', 'bodyweight', 2, 28, 3, 6, 12, 'reps', 60, 'Rapatkan kedua tangan di bawah dada hingga ibu jari dan telunjuk membentuk segitiga atau berlian. Turunkan dada mendekati tangan lalu dorong naik untuk melatih dada dalam dan trisep.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('acd7351c-ede1-48e5-965d-2e9723ca9461', 'EX45', 'Archer push-up', 'horizontal_push', 'chest', 'bodyweight', 2, 29, 3, 6, 10, 'reps', 75, 'Buka tangan jauh lebih lebar dari bahu. Turunkan tubuh condong ke satu sisi sambil meluruskan lengan lainnya, dorong kembali, lalu bergantian sisi.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('a2c0be8a-275b-4da3-adff-a26f503be945', 'EX46', 'Explosive push-up', 'horizontal_push', 'chest', 'bodyweight', 2, 30, 3, 5, 10, 'reps', 90, 'Lakukan push-up lalu dorong tubuh dengan kuat ke atas hingga telapak tangan terangkat ringan dari lantai. Mendarat dengan siku sedikit menekuk untuk meredam benturan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6f4a3d2f-ccc2-4038-82c1-83cd54cd8d34', 'EX47', 'Parallel bar / chair chest dips', 'horizontal_push', 'chest', 'bodyweight', 2, 31, 3, 6, 12, 'reps', 90, 'Bertumpu pada dua palang sejajar atau dua kursi kokoh, condongkan tubuh sedikit ke depan. Turunkan tubuh perlahan lalu dorong kembali ke atas.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9942086e-76ac-4807-81d9-968837bb1ba5', 'EX48', 'Close-grip lat pulldown', 'vertical_pull', 'back', 'gym', 1, 10, 3, 8, 12, 'reps', 90, 'Gunakan pegangan V-bar atau genggaman sempit pada mesin pulldown. Tarik pegangan ke dada atas sambil menarik siku dekat ke rusuk lalu kembalikan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('f95baf71-94d5-4928-8095-b030f8ecaf07', 'EX49', 'Underhand lat pulldown', 'vertical_pull', 'back', 'gym', 1, 11, 3, 8, 12, 'reps', 90, 'Genggam bar selebar bahu dengan telapak tangan menghadap wajah. Tarik bar ke dada atas dengan fokus mengaktifkan latissimus dan bisep lalu naikkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('2aa3366a-fa5b-4cad-93dc-ac6ec75fd5e6', 'EX50', 'Straight-arm cable pulldown', 'vertical_pull', 'back', 'gym', 1, 12, 3, 10, 15, 'reps', 60, 'Berdiri menghadap puli tinggi, pegang bar atau tali dengan lengan hampir lurus. Tarik ke bawah hingga menyentuh paha sambil mengencangkan otot sayap punggung.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9124c9f4-9519-4129-ad71-26036f8f3c35', 'EX51', 'Barbell bent-over row', 'horizontal_pull', 'back', 'gym', 2, 13, 4, 6, 10, 'reps', 120, 'Condongkan tubuh sekitar 45 derajat dengan punggung lurus dan lutut sedikit ditekuk. Tarik barbel ke arah perut bawah sambil merapatkan belikat lalu turunkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('77364a82-3130-4310-a2c2-f78130944d18', 'EX52', 'Pendlay row', 'horizontal_pull', 'back', 'gym', 2, 14, 3, 6, 8, 'reps', 120, 'Condongkan punggung sejajar lantai dengan barbel bertumpu di lantai di awal setiap repetisi. Tarik eksplosif ke dada bawah lalu turunkan kembali hingga menyentuh lantai.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('45b8eefe-75b2-49d3-bc95-91ff3d9b25fc', 'EX53', 'T-Bar row', 'horizontal_pull', 'back', 'gym', 2, 15, 3, 8, 12, 'reps', 90, 'Berdiri mengangkangi landmine atau mesin T-Bar dengan punggung lurus. Tarik pegangan ke arah dada bawah dengan merapatkan tulang belikat lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('79064b2d-7778-46f3-868a-f9653fe5a398', 'EX54', 'Chest-supported machine row', 'horizontal_pull', 'back', 'gym', 1, 16, 3, 8, 12, 'reps', 90, 'Tempelkan dada pada bantalan mesin row agar punggung bawah tetap stabil. Tarik handel ke belakang sambil meremas punggung tengah lalu kembalikan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9ba06b4f-fb4b-446a-97dc-4e44cafa541e', 'EX55', 'Single-arm cable row', 'horizontal_pull', 'back', 'gym', 1, 17, 3, 10, 12, 'reps', 60, 'Duduk atau berdiri stabil dengan satu pegangan kabel. Tarik handel ke arah pinggul satu sisi secara bergantian tanpa memutar bahu berlebihan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('2b805b62-e8ec-452d-bef8-5f0f755302a5', 'EX56', 'Cable face pull', 'horizontal_pull', 'back', 'gym', 1, 18, 3, 12, 15, 'reps', 60, 'Atur puli setinggi wajah dengan tali rope. Tarik tali ke arah dahi sambil membuka kedua siku ke samping dan memutar bahu keluar untuk melatih punggung atas dan rear delt.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('75b7893f-2812-4f90-a2b7-694b0f3ad0c6', 'EX57', 'Back extension (hyperextension)', 'hinge', 'back', 'gym', 1, 19, 3, 10, 15, 'reps', 60, 'Posisikan pinggul pada bantalan kursi hyperextension dengan kaki terkunci. Turunkan tubuh terkontrol lalu naikkan kembali hingga tubuh lurus sejajar kaki.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('84490b77-e58b-4860-816d-e542f5aa3301', 'EX58', 'Barbell shrug', 'carry', 'back', 'gym', 1, 20, 3, 10, 15, 'reps', 60, 'Berdiri tegak memegang barbel di depan paha. Angkat bahu lurus ke arah telinga, tahan 1 detik di puncak, lalu turunkan perlahan tanpa memutar bahu.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('b7b6328f-120c-4e4b-83ef-a53c8ad3130c', 'EX59', 'Rack pull', 'hinge', 'back', 'gym', 2, 21, 3, 5, 8, 'reps', 120, 'Letakkan barbel pada safety pin power rack setinggi lutut. Punggung netral, dorong pinggul maju untuk mengangkat bar hingga berdiri tegak lalu turunkan kembali ke pin.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('2366f0da-74a2-4d47-b179-d8968a0ab72d', 'EX60', 'Bent-over dumbbell row', 'horizontal_pull', 'back', 'dumbbell', 1, 22, 3, 8, 12, 'reps', 90, 'Pegang sepasang dumbbell, condongkan tubuh 45 derajat dengan punggung lurus. Tarik kedua dumbbell bersamaan ke arah pinggul sambil merapatkan belikat.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('13a9a7f1-4c7e-47f2-9d49-3141cd311f49', 'EX61', 'Chest-supported dumbbell row', 'horizontal_pull', 'back', 'dumbbell', 1, 23, 3, 8, 12, 'reps', 90, 'Berbaring telungkup di incline bench 30–45 derajat sambil memegang dumbbell. Tarik siku ke belakang mendekati pinggul untuk menargetkan punggung atas tanpa membebani pinggang.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('8dbbe5e1-8595-4000-b272-f27ae2c4bfb4', 'EX62', 'Dumbbell shrug', 'carry', 'back', 'dumbbell', 1, 24, 3, 10, 15, 'reps', 60, 'Berdiri tegak memegang dumbbell di samping tubuh. Angkat bahu ke atas mendekati telinga untuk melatih trapezius, tahan sejenak, lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('886b8941-9195-4ad8-8874-1b5bca56d7aa', 'EX63', 'Dumbbell renegade row', 'horizontal_pull', 'back', 'dumbbell', 2, 25, 3, 8, 12, 'reps', 75, 'Posisi plank bertumpu pada sepasang dumbbell dengan kaki agak lebar. Tarik satu dumbbell ke pinggul secara bergantian sambil menjaga pinggul tetap stabil tanpa berputar.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('8a46b217-71b9-44cb-87e2-1c4f206f93c4', 'EX64', 'Pull-up', 'vertical_pull', 'back', 'bodyweight', 2, 26, 3, 4, 10, 'reps', 120, 'Genggam palang pull-up sedikit lebih lebar dari bahu dengan telapak menghadap depan. Tarik tubuh hingga dagu melewati palang lalu turunkan kembali sampai lengan lurus terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('8c1dda42-d2b1-4a10-b894-b62642629b6c', 'EX65', 'Chin-up', 'vertical_pull', 'back', 'bodyweight', 2, 27, 3, 5, 10, 'reps', 120, 'Genggam palang selebar bahu dengan telapak tangan menghadap wajah. Tarik tubuh ke atas hingga dagu melewati palang untuk melatih punggung dan bisep lalu turun perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('43779454-f6b0-429c-ae1b-c59fb64170ec', 'EX66', 'Inverted row / Australian pull-up', 'horizontal_pull', 'back', 'bodyweight', 2, 28, 3, 8, 15, 'reps', 75, 'Berbaring di bawah palang rendah atau meja kokoh, pegang palang selebar bahu dengan tubuh lurus. Tarik dada menyentuh palang sambil merapatkan belikat lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('80c64c6c-1c27-4066-962a-6b9ed2e40fc8', 'EX67', 'Superman hold', 'hinge', 'back', 'bodyweight', 1, 29, 3, 20, 40, 'seconds', 45, 'Berbaring telungkup di matras dengan lengan lurus ke depan. Angkat lengan, dada, dan kaki secara bersamaan beberapa sentimeter dari lantai lalu tahan sambil bernapas.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('a017f876-99e5-4afa-8aa1-fd142b2e8d06', 'EX68', 'Reverse snow angel', 'horizontal_pull', 'back', 'bodyweight', 1, 30, 3, 10, 15, 'reps', 45, 'Berbaring telungkup dengan lengan lurus di samping paha. Angkat lengan sedikit dari lantai lalu ayunkan membentuk setengah lingkaran hingga ke atas kepala dan kembali perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('651aa5de-5345-4fc1-9732-4ef24d56fd70', 'EX69', 'Doorframe / towel row', 'horizontal_pull', 'back', 'bodyweight', 1, 31, 3, 10, 15, 'reps', 60, 'Pegang kusen pintu kokoh atau handuk yang dikaitkan aman, condongkan tubuh ke belakang dengan lengan lurus. Tarik dada mendekati tumpuan sambil mengaktifkan punggung.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('aca8d79b-c065-4766-9743-ea05edf26892', 'EX70', 'Prone cobra hold', 'hinge', 'back', 'bodyweight', 1, 32, 3, 20, 40, 'seconds', 45, 'Berbaring telungkup, angkat dada sedikit dari lantai sambil menarik bahu ke belakang dan memutar ibu jari menghadap langit-langit. Tahan sesuai durasi.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('33932030-be93-463e-b258-61d3725c64ab', 'EX71', 'Overhead barbell press (OHP)', 'vertical_push', 'shoulders', 'gym', 2, 10, 4, 6, 10, 'reps', 120, 'Berdiri tegak dengan barbel di depan bahu atas dan inti tubuh kencang. Dorong barbel lurus ke atas kepala hingga lengan lurus lalu turunkan terkontrol ke tulang selangka.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('39243168-999d-4266-ae51-3b485cbc3331', 'EX72', 'Smith machine shoulder press', 'vertical_push', 'shoulders', 'gym', 1, 11, 3, 8, 12, 'reps', 90, 'Duduk tegak di bench sandaran tinggi di bawah Smith machine. Dorong bar ke atas kepala secara stabil lalu turunkan sejajar dagu atau bahu.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('781007a6-b843-4e99-b14b-568a26f85ade', 'EX73', 'Cable lateral raise', 'vertical_push', 'shoulders', 'gym', 1, 12, 3, 12, 15, 'reps', 60, 'Berdiri menyamping dari puli bawah, pegang handel dengan tangan sisi jauh. Angkat lengan ke samping hingga sejajar bahu dengan siku sedikit ditekuk lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('d77fc190-edb1-439a-8968-e4d7b5e31596', 'EX74', 'Cable front raise', 'vertical_push', 'shoulders', 'gym', 1, 13, 3, 10, 15, 'reps', 60, 'Berdiri membelakangi puli bawah, pegang tali atau handel di depan paha. Angkat lengan lurus ke depan hingga setinggi bahu untuk melatih bahu depan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('70178c34-3253-46ed-8867-b5322fff49c2', 'EX75', 'Reverse pec deck fly', 'horizontal_pull', 'shoulders', 'gym', 1, 14, 3, 12, 15, 'reps', 60, 'Duduk menghadap sandaran mesin pec deck, pegang handel dengan lengan lurus ke depan. Tarik lengan ke belakang secara melebar untuk melatih bahu belakang.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('dce6daa1-65e8-4c52-ab6b-a702714cb5df', 'EX76', 'Cable rear delt fly', 'horizontal_pull', 'shoulders', 'gym', 1, 15, 3, 12, 15, 'reps', 60, 'Atur kabel setinggi bahu tanpa pegangan atau gunakan handel silang. Tarik kedua tangan melebar ke samping belakang dengan fokus otot deltoid posterior.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('2f9ad596-3f85-4f85-a9a8-651b9cd28144', 'EX77', 'Upright barbell row', 'vertical_push', 'shoulders', 'gym', 2, 16, 3, 8, 12, 'reps', 75, 'Berdiri memegang barbel selebar bahu di depan paha. Tarik bar mendekati dada atas dengan memimpin gerakan melalui siku, hindari mengangkat siku terlalu tinggi jika bahu tidak nyaman.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('71686a7a-737b-4f45-bfa1-83dba8cca180', 'EX78', 'Landmine press', 'vertical_push', 'shoulders', 'gym', 1, 17, 3, 8, 12, 'reps', 75, 'Berdiri atau berlutut setengah, pegang ujung barbel landmine di depan bahu. Dorong ke atas diagonal hingga lengan lurus sambil mengencangkan perut.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('2c3607a7-be8d-41a0-873e-e8f49494909c', 'EX79', 'Arnold press', 'vertical_push', 'shoulders', 'dumbbell', 2, 18, 3, 8, 12, 'reps', 90, 'Duduk tegak memegang dumbbell di depan bahu dengan telapak menghadap wajah. Putar telapak menghadap depan saat mendorong ke atas kepala lalu putar kembali saat turun.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('45cb6ab5-ac62-4031-9231-d12e525fa832', 'EX80', 'Dumbbell lateral raise', 'vertical_push', 'shoulders', 'dumbbell', 1, 19, 3, 12, 15, 'reps', 60, 'Berdiri tegak memegang dumbbell di samping paha. Angkat kedua lengan ke samping hingga sejajar bahu tanpa mengayunkan punggung lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('55b1aaf0-c742-4ad3-bde7-4d72f1c0ed22', 'EX81', 'Dumbbell front raise', 'vertical_push', 'shoulders', 'dumbbell', 1, 20, 3, 10, 15, 'reps', 60, 'Berdiri tegak memegang dumbbell di depan paha. Angkat satu atau kedua dumbbell ke depan hingga setinggi bahu dengan siku sedikit ditekuk.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6653702e-ff1c-4ee4-9ec7-7282964fc965', 'EX82', 'Bent-over dumbbell rear delt fly', 'horizontal_pull', 'shoulders', 'dumbbell', 1, 21, 3, 12, 15, 'reps', 60, 'Condongkan tubuh hampir sejajar lantai dengan punggung lurus. Angkat kedua dumbbell ke samping menjauhi tubuh untuk menargetkan bahu belakang.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('b9304129-4930-408f-a8ba-d7c52456dbce', 'EX83', 'Dumbbell upright row', 'vertical_push', 'shoulders', 'dumbbell', 1, 22, 3, 10, 12, 'reps', 75, 'Berdiri memegang dumbbell di depan paha. Tarik dumbbell ke arah dada atas dengan siku mengarah ke samping lalu turunkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('ced4a99b-affe-4478-a471-b6f4effa8df4', 'EX84', 'Elevated pike push-up', 'vertical_push', 'shoulders', 'bodyweight', 2, 23, 3, 6, 12, 'reps', 75, 'Letakkan kaki di atas bangku dan tangan di lantai membentuk sudut V tajam. Turunkan puncak kepala mendekati lantai di depan garis tangan lalu dorong naik.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('98c0466b-2d16-4fbf-a102-3bc1060360e8', 'EX85', 'Wall handstand hold', 'vertical_push', 'shoulders', 'bodyweight', 2, 24, 3, 15, 40, 'seconds', 75, 'Lakukan handstand menghadap atau membelakangi dinding dengan lengan lurus kuat dan perut kencang. Tahan posisi stabil selama durasi set.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('d0d74fde-c80c-448b-9d49-4a41ebd4626a', 'EX86', 'Wall handstand push-up', 'vertical_push', 'shoulders', 'bodyweight', 2, 25, 3, 3, 8, 'reps', 120, 'Dari posisi handstand bersandar dinding, tekuk siku perlahan hingga kepala mendekati matras lalu dorong tubuh kembali lurus ke atas.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('f1dc54fb-214d-4dd5-a6c7-fd475610e869', 'EX87', 'Shoulder tap plank', 'vertical_push', 'shoulders', 'bodyweight', 1, 26, 3, 12, 20, 'reps', 45, 'Ambil posisi high plank dengan tangan sejajar bahu dan kaki agak lebar. Sentuh bahu berlawanan secara bergantian tanpa menggoyangkan pinggul.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.221239', '2026-11-19T21:48:12.221239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('bda28d8c-2a93-46bf-b493-acf43ad6af5d', 'EX88', 'Arm circles (isometric shoulder)', 'vertical_push', 'shoulders', 'bodyweight', 1, 27, 3, 30, 45, 'seconds', 30, 'Berdiri tegak rentangkan kedua lengan ke samping sejajar bahu. Putar lengan membentuk lingkaran kecil ke depan lalu ke belakang untuk melatih daya tahan bahu.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9a68a34c-b36e-49a8-aa32-1ea039cc4802', 'EX89', 'Barbell front squat', 'squat', 'legs', 'gym', 2, 10, 4, 6, 10, 'reps', 120, 'Letakkan barbel di bahu depan dengan posisi front rack atau lengan menyilang, siku tinggi. Turun squat dengan dada tegak lalu dorong naik melalui telapak kaki.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('18e7ffd5-1f2d-4393-9447-457491797f43', 'EX90', 'Hack squat machine', 'squat', 'legs', 'gym', 1, 11, 3, 8, 12, 'reps', 90, 'Tempelkan punggung dan bahu pada bantalan mesin hack squat, kaki selebar bahu. Turun hingga lutut tertekuk dalam lalu dorong naik tanpa mengunci lutut.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('29fd72bc-3e43-4b30-9446-65144cf7f1c3', 'EX91', 'Smith machine squat', 'squat', 'legs', 'gym', 1, 12, 3, 8, 12, 'reps', 90, 'Posisikan bar Smith machine di punggung atas, langkahkan kaki sedikit ke depan. Turun terkontrol hingga paha sejajar lantai lalu dorong berdiri.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('4be678e7-dcf5-4039-9bdc-b36993dfc7a2', 'EX92', 'Leg extension machine', 'squat', 'legs', 'gym', 1, 13, 3, 10, 15, 'reps', 60, 'Duduk dengan lutut sejajar poros mesin dan bantalan di pergelangan kaki depan. Luruskan kedua kaki ke atas sambil mengencangkan paha depan lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('bfc68fc7-36a5-45a6-af44-f39b9237aba9', 'EX93', 'Lying leg curl machine', 'hinge', 'hamstrings', 'gym', 1, 14, 3, 10, 15, 'reps', 60, 'Berbaring telungkup di mesin leg curl dengan bantalan di atas tumit. Tekuk lutut menarik bantalan mendekati bokong tanpa mengangkat pinggul lalu kembalikan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('8281c879-1ab8-424c-bff3-e19f5d021a25', 'EX94', 'Seated leg curl machine', 'hinge', 'hamstrings', 'gym', 1, 15, 3, 10, 15, 'reps', 60, 'Duduk tegak dengan bantalan pengunci di atas paha dan roller di belakang tumit. Tarik tumit ke bawah kursi untuk mengaktifkan hamstring lalu lepas perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('24f89372-687e-4afb-85b6-dfc3841f1c70', 'EX95', 'Conventional barbell deadlift', 'hinge', 'hamstrings', 'gym', 2, 16, 3, 5, 8, 'reps', 150, 'Berdiri dengan tengah telapak kaki di bawah barbel, genggam bar di luar lutut, punggung netral. Dorong lantai melalui kaki dan luruskan pinggul hingga berdiri tegak lalu turunkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('90964a66-9a36-4a7c-a3d1-418635f151cc', 'EX96', 'Sumo barbell deadlift', 'hinge', 'glutes', 'gym', 2, 17, 3, 5, 8, 'reps', 150, 'Buka kaki lebar dengan ujung kaki mengarah keluar dan pegang bar di bagian dalam lutut. Dada tegak, dorong lantai melalui kaki untuk mengangkat bar hingga berdiri.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('222f78d7-d093-4f95-80f8-444bb9496924', 'EX97', 'Barbell hip thrust', 'hinge', 'glutes', 'gym', 2, 18, 4, 8, 12, 'reps', 90, 'Sandarkan punggung atas di bench dengan barbel berbantalan di lipatan pinggul. Dorong pinggul naik hingga sejajar bahu dan lutut, remas glutes 1 detik, lalu turunkan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('15b96cbe-b46c-4b99-bfb1-f0f4e413241d', 'EX98', 'Cable glute kickback', 'hinge', 'glutes', 'gym', 1, 19, 3, 12, 15, 'reps', 60, 'Pasang ankle strap pada puli bawah, berdiri menghadap mesin sambil berpegangan. Tendang kaki lurus ke belakang sambil mengencangkan glutes tanpa melengkungkan pinggang.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('63dbfd8c-0794-43a5-abd2-74781e8a8cbd', 'EX99', 'Hip abduction machine', 'lunge', 'glutes', 'gym', 1, 20, 3, 12, 15, 'reps', 60, 'Duduk tegak di mesin hip abduction dengan bantalan di sisi luar paha. Dorong kedua paha melebar ke luar untuk melatih glute medius lalu rapatkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('237531b8-e734-4585-a7f8-50e848a68978', 'EX100', 'Hip adduction machine', 'lunge', 'legs', 'gym', 1, 21, 3, 12, 15, 'reps', 60, 'Duduk di mesin hip adduction dengan bantalan di sisi dalam paha. Rapatkan kedua paha terkontrol untuk melatih paha bagian dalam lalu buka kembali perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9a9fdb7c-fa59-44b4-957a-d3f4ac219695', 'EX101', 'Standing calf raise machine', 'squat', 'calves', 'gym', 1, 22, 3, 12, 15, 'reps', 60, 'Berdiri dengan ujung kaki di pijakan dan bahu di bawah bantalan. Jinjit setinggi mungkin, tahan 1 detik, lalu turunkan tumit melewati pijakan untuk regangan penuh.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('75c792fc-a41c-4f08-8362-e7c5f319f153', 'EX102', 'Seated calf raise machine', 'squat', 'calves', 'gym', 1, 23, 3, 12, 15, 'reps', 60, 'Duduk dengan bantalan beban di atas lutut dan ujung kaki di pijakan. Angkat tumit setinggi mungkin untuk melatih otot soleus betis lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6de9e34f-4644-4a34-a23b-a9156a43cde5', 'EX103', 'Dumbbell Bulgarian split squat', 'lunge', 'legs', 'dumbbell', 2, 24, 3, 8, 12, 'reps', 90, 'Pegang dumbbell di samping tubuh, letakkan punggung kaki belakang di atas bench. Turunkan pinggul hingga paha depan sejajar lantai lalu dorong naik melalui kaki depan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('3d6c98f6-8cb4-4abf-964d-ce58ae2fdc37', 'EX104', 'Dumbbell walking lunge', 'lunge', 'legs', 'dumbbell', 1, 25, 3, 10, 14, 'reps', 75, 'Pegang dumbbell di samping tubuh lalu melangkah maju bergantian. Turunkan lutut belakang mendekati lantai dengan batang tubuh tegak lalu dorong maju ke langkah berikutnya.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5bed9874-5246-4da6-9063-93e1a047a010', 'EX105', 'Dumbbell step-up', 'lunge', 'legs', 'dumbbell', 1, 26, 3, 8, 12, 'reps', 75, 'Pegang dumbbell di samping tubuh, pijakkan satu kaki di atas box atau bangku kokoh. Dorong tubuh naik melalui kaki di atas box lalu turun perlahan dan bergantian.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('4849f18f-16ac-4da8-9905-6074fc3e9030', 'EX106', 'Dumbbell sumo squat', 'squat', 'glutes', 'dumbbell', 1, 27, 3, 10, 15, 'reps', 75, 'Buka kaki lebar dengan jari kaki mengarah keluar, pegang satu dumbbell vertikal di antara kaki. Turun dalam dengan dada tegak lalu dorong naik sambil meremas glutes.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6349bdc0-ddf3-4dd4-bfee-cc23a565f619', 'EX107', 'Dumbbell hip thrust', 'hinge', 'glutes', 'dumbbell', 1, 28, 3, 10, 15, 'reps', 75, 'Sandarkan punggung atas di bench sambil menaruh dumbbell di atas pinggul. Dorong pinggul naik hingga tubuh rata dari bahu ke lutut lalu turunkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('24678731-6667-4f95-84fc-ed2b0ece363a', 'EX108', 'Dumbbell standing calf raise', 'squat', 'calves', 'dumbbell', 1, 29, 3, 12, 20, 'reps', 45, 'Berdiri memegang dumbbell di samping tubuh di lantai atau tepi tangga. Angkat tumit setinggi mungkin, tahan sejenak, lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5d49b346-ef08-45f5-866c-069a32bf2afe', 'EX109', 'Sumo bodyweight squat', 'squat', 'glutes', 'bodyweight', 1, 30, 3, 12, 20, 'reps', 60, 'Buka kaki lebih lebar dari bahu dengan ujung kaki mengarah 45 derajat keluar. Turunkan pinggul dengan lutut mengikuti arah jari kaki lalu berdiri kembali.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('48ab1b41-011f-4ec0-b186-07b35acd027a', 'EX110', 'Jump squat', 'squat', 'legs', 'bodyweight', 2, 31, 3, 8, 15, 'reps', 75, 'Turun ke posisi squat lalu lompat ke atas secara eksplosif. Mendarat lembut dengan lutut sedikit menekuk dan langsung masuk ke repetisi berikutnya.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('cf6c3aa9-0a3f-4f1b-93a3-d8bd1460fc05', 'EX111', 'Bulgarian split squat (bodyweight)', 'lunge', 'legs', 'bodyweight', 2, 32, 3, 10, 15, 'reps', 75, 'Letakkan satu kaki di belakang di atas kursi atau sofa. Turunkan pinggul hingga paha depan sejajar lantai sambil menjaga keseimbangan lalu dorong naik.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('0a237f0c-fa34-44b4-9ece-476d04760d93', 'EX112', 'Forward lunge', 'lunge', 'legs', 'bodyweight', 1, 33, 3, 10, 14, 'reps', 60, 'Langkahkan satu kaki ke depan dan turunkan tubuh hingga kedua lutut membentuk 90 derajat. Dorong kembali melalui kaki depan ke posisi berdiri.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('397cf7d4-f31c-42bc-af64-9c92cbb4b862', 'EX113', 'Walking lunge (bodyweight)', 'lunge', 'legs', 'bodyweight', 1, 34, 3, 12, 20, 'reps', 60, 'Lakukan lunge maju terus menerus secara bergantian kanan dan kiri sambil menjaga punggung tegak dan inti kencang.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9dad2290-674c-4692-98e2-233f081c9b1c', 'EX114', 'Side lunge (lateral lunge)', 'lunge', 'legs', 'bodyweight', 1, 35, 3, 10, 12, 'reps', 60, 'Langkahkan satu kaki jauh ke samping, tekuk lutut sisi tersebut sambil meluruskan kaki lainnya dan mendorong pinggul ke belakang. Kembali ke tengah lalu ganti sisi.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('4d9e0f0d-8873-48f7-92ca-8214dde49d79', 'EX115', 'Curtsy lunge', 'lunge', 'glutes', 'bodyweight', 1, 36, 3, 10, 14, 'reps', 60, 'Langkahkan satu kaki menyilang ke belakang kaki lainnya lalu tekuk kedua lutut. Dorong kembali ke berdiri untuk melatih glutes samping dan paha.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('1e0eceb0-6500-4f17-90a2-7a9df9972117', 'EX116', 'Single-leg glute bridge', 'hinge', 'glutes', 'bodyweight', 2, 37, 3, 8, 12, 'reps', 60, 'Berbaring telentang dengan satu lutut ditekuk dan kaki lain diluruskan. Dorong pinggul naik menggunakan satu kaki penumpu sambil menjaga panggul sejajar.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('4e49bf62-1e24-4b52-9e02-ef9802af7105', 'EX117', 'Donkey kick', 'hinge', 'glutes', 'bodyweight', 1, 38, 3, 12, 15, 'reps', 45, 'Posisi merangkak dengan tangan sejajar bahu dan lutut sejajar pinggul. Tendang satu kaki ke atas belakang dengan lutut tetap ditekuk 90 derajat tanpa melengkungkan punggung.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('68f61c8e-918a-48ab-90d5-f8a9e44e9f6f', 'EX118', 'Fire hydrant', 'lunge', 'glutes', 'bodyweight', 1, 39, 3, 12, 15, 'reps', 45, 'Dari posisi merangkak, angkat satu lutut melebar ke samping setinggi pinggul sambil menjaga inti kencang lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('a756e22d-921d-4f54-9fb8-34edf4cdd47c', 'EX119', 'Wall sit', 'squat', 'legs', 'bodyweight', 1, 40, 3, 30, 60, 'seconds', 60, 'Sandarkan punggung rata di dinding lalu turunkan tubuh hingga paha sejajar lantai dan lutut 90 derajat. Tahan posisi isometrik sesuai durasi.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('1ba5954d-0c87-4e13-9b9a-b4a1bf71dee9', 'EX120', 'Bodyweight step-up', 'lunge', 'legs', 'bodyweight', 1, 41, 3, 10, 15, 'reps', 60, 'Naikkan satu kaki ke atas tangga atau kursi kokoh lalu angkat seluruh tubuh hingga berdiri di atasnya. Turun terkontrol dan ganti kaki.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('eb519f61-65d1-4952-ad7c-93d05365a4b8', 'EX121', 'Standing calf raise (bodyweight)', 'squat', 'calves', 'bodyweight', 1, 42, 3, 15, 25, 'reps', 45, 'Berdiri tegak di lantai atau tepi anak tangga, pegang dinding untuk keseimbangan bila perlu. Jinjit setinggi mungkin lalu turunkan tumit perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9801140c-89a6-4ce1-95eb-a8e41486196a', 'EX122', 'Single-leg calf raise', 'squat', 'calves', 'bodyweight', 2, 43, 3, 12, 15, 'reps', 45, 'Bertumpu pada satu kaki sambil berpegangan ringan pada dinding. Jinjit setinggi mungkin dengan satu betis lalu turunkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('cfe67e4f-11aa-439b-b18f-e01718e8598c', 'EX123', 'Assisted pistol squat', 'squat', 'legs', 'bodyweight', 2, 44, 3, 5, 10, 'reps', 90, 'Pegang kusen pintu atau tiang kokoh, luruskan satu kaki ke depan. Turun squat satu kaki sedalam yang nyaman lalu dorong berdiri kembali.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('7702a79e-2e84-48e4-9eb2-3e283c80cd52', 'EX124', 'Nordic hamstring negative', 'hinge', 'hamstrings', 'bodyweight', 2, 45, 3, 5, 8, 'reps', 90, 'Berlutut di matras dengan pergelangan kaki tertahan di bawah sofa kokoh atau dipegang rekan. Condongkan tubuh lurus ke depan selambat mungkin menggunakan hamstring lalu tangkap dengan tangan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('bbb365c4-e3c5-4565-9d81-ac03bb63a93a', 'EX125', 'Barbell bicep curl', 'horizontal_pull', 'biceps', 'gym', 1, 20, 3, 8, 12, 'reps', 60, 'Berdiri tegak memegang barbel lurus selebar bahu dengan telapak menghadap depan. Tekuk siku mengangkat bar ke arah bahu tanpa mengayunkan punggung lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('59a9ad2a-38b3-4695-aea1-904c9ee458ba', 'EX126', 'EZ-bar bicep curl', 'horizontal_pull', 'biceps', 'gym', 1, 21, 3, 8, 12, 'reps', 60, 'Pegang EZ-bar pada lekukan ergonomis agar pergelangan tangan nyaman. Angkat bar ke arah dada atas sambil mengencangkan bisep lalu turunkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('52903b23-9bfe-470f-8dd1-202591e120e0', 'EX127', 'Preacher curl machine', 'horizontal_pull', 'biceps', 'gym', 1, 22, 3, 10, 12, 'reps', 60, 'Sandarkan lengan atas penuh pada bantalan preacher. Tekuk siku menarik pegangan ke atas untuk isolasi bisep lalu turunkan hampir lurus tanpa menghentak.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('151ee68c-f1af-47a9-ae3a-4ac0bb6e97e3', 'EX128', 'Cable bicep curl', 'horizontal_pull', 'biceps', 'gym', 1, 23, 3, 10, 15, 'reps', 60, 'Gunakan puli bawah dengan straight bar atau EZ attachment. Jaga siku tetap di sisi tubuh, tarik bar ke arah bahu lalu turunkan perlahan menjaga tegangan konstan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('2867b4f1-e3cb-4cd2-b57e-e7cf3d9785bd', 'EX129', 'Cable rope hammer curl', 'horizontal_pull', 'biceps', 'gym', 1, 24, 3, 10, 15, 'reps', 60, 'Pegang tali rope di puli bawah dengan genggaman netral (ibu jari menghadap atas). Tarik tali ke arah bahu untuk melatih bisep dan brachialis.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('1d0702bf-53ff-4a83-9cc0-afdfa1c45abe', 'EX130', 'Cable tricep rope pushdown', 'horizontal_push', 'triceps', 'gym', 1, 20, 3, 10, 15, 'reps', 60, 'Berdiri menghadap puli atas dengan tali rope, siku rapat di samping rusuk. Dorong tali ke bawah hingga lengan lurus dan buka sedikit ujung tali di bawah lalu kembalikan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('2995be4e-05c0-4a21-84f0-a4c6d32cbc01', 'EX131', 'Cable straight-bar tricep pushdown', 'horizontal_push', 'triceps', 'gym', 1, 21, 3, 10, 15, 'reps', 60, 'Pegang bar lurus pada puli atas dengan siku terkunci di samping tubuh. Dorong bar ke bawah hingga trisep berkontraksi penuh lalu kembalikan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('079a35a4-2889-415b-be5e-8e6c2d1b7299', 'EX132', 'Cable overhead tricep extension', 'vertical_push', 'triceps', 'gym', 1, 22, 3, 10, 15, 'reps', 60, 'Berdiri membelakangi mesin kabel dengan tali rope di atas kepala. Luruskan siku ke depan atas untuk melatih kepala panjang trisep lalu tekuk kembali di belakang kepala.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('62b8cdae-648c-4c80-b2ea-3818aa9863ac', 'EX133', 'EZ-bar skull crusher', 'horizontal_push', 'triceps', 'gym', 2, 23, 3, 8, 12, 'reps', 75, 'Berbaring di bench datar memegang EZ-bar lurus di atas dada. Tekuk siku menurunkan bar ke arah dahi atau belakang kepala lalu luruskan kembali.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('00238ef7-520b-4b45-af16-3d6ac0a4ab67', 'EX134', 'Close-grip barbell bench press', 'horizontal_push', 'triceps', 'gym', 2, 24, 3, 6, 10, 'reps', 90, 'Berbaring di bench datar dengan genggaman bar selebar bahu. Turunkan bar ke dada bawah dengan siku rapat ke tubuh lalu dorong naik memaksimalkan trisep.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('22fbd677-dc50-4fb5-b0cc-2608e9f076a8', 'EX135', 'Tricep dip machine', 'horizontal_push', 'triceps', 'gym', 1, 25, 3, 10, 12, 'reps', 60, 'Duduk tegak di mesin dip, genggam handel di samping tubuh. Dorong handel lurus ke bawah hingga lengan hampir lurus lalu kembalikan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6615751f-60d2-444a-a371-a05d74abd3f3', 'EX136', 'Dumbbell bicep curl', 'horizontal_pull', 'biceps', 'dumbbell', 1, 26, 3, 10, 15, 'reps', 60, 'Berdiri tegak memegang dumbbell di samping paha. Tekuk siku mengangkat dumbbell ke arah bahu dengan telapak menghadap atas lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('81c83877-0b87-43cb-8223-4ce437e881e6', 'EX137', 'Dumbbell hammer curl', 'horizontal_pull', 'biceps', 'dumbbell', 1, 27, 3, 10, 15, 'reps', 60, 'Pegang dumbbell dengan telapak menghadap ke dalam (genggaman palu). Angkat dumbbell ke arah bahu tanpa mengayunkan bahu untuk melatih bisep dan lengan bawah.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('a1397d5d-4827-4bf3-a933-58c71d03b39f', 'EX138', 'Dumbbell concentration curl', 'horizontal_pull', 'biceps', 'dumbbell', 1, 28, 3, 10, 12, 'reps', 60, 'Duduk di bench, sandarkan siku kanan di sisi dalam paha kanan. Angkat dumbbell dengan isolasi penuh otot bisep lalu turunkan perlahan dan ganti lengan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('972fb295-675d-4c3a-a3a0-4f51cbba0846', 'EX139', 'Incline dumbbell bicep curl', 'horizontal_pull', 'biceps', 'dumbbell', 2, 29, 3, 8, 12, 'reps', 75, 'Berbaring di incline bench 45 derajat dengan kedua lengan menggantung lurus ke bawah. Tekuk siku mengangkat dumbbell tanpa memajukan siku untuk regangan bisep maksimal.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('e72b52d6-6313-42be-b92f-58a773c2ff2c', 'EX140', 'Dumbbell overhead tricep extension', 'vertical_push', 'triceps', 'dumbbell', 1, 26, 3, 10, 12, 'reps', 60, 'Duduk atau berdiri memegang satu dumbbell dengan kedua tangan di atas kepala. Turunkan dumbbell ke belakang kepala dengan siku tetap mengarah ke atas lalu luruskan kembali.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6377e442-4c4f-4d71-ac70-10df303cca00', 'EX141', 'Dumbbell tricep kickback', 'horizontal_push', 'triceps', 'dumbbell', 1, 27, 3, 12, 15, 'reps', 60, 'Condongkan tubuh ke depan dengan siku terangkat sejajar punggung. Luruskan lengan bawah ke belakang sambil mengencangkan trisep lalu tekuk kembali 90 derajat.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('80de4eea-acba-44e6-b6da-411094642ed5', 'EX142', 'Dumbbell skull crusher', 'horizontal_push', 'triceps', 'dumbbell', 2, 28, 3, 8, 12, 'reps', 75, 'Berbaring di bench datar memegang sepasang dumbbell lurus di atas bahu. Tekuk siku menurunkan dumbbell ke samping kepala lalu dorong lurus kembali.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('26d08c43-d8cb-4c9b-815d-b7dec16df14e', 'EX143', 'Dumbbell wrist curl', 'carry', 'biceps', 'dumbbell', 1, 29, 3, 12, 20, 'reps', 45, 'Duduk dengan lengan bawah bertumpu di paha atau bench dan telapak menghadap atas. Tekuk pergelangan tangan ke atas untuk melatih otot forearm lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('bde7668f-5a81-485d-a46c-bfcc7ecb0aed', 'EX144', 'Chair / bench tricep dips', 'horizontal_push', 'triceps', 'bodyweight', 1, 32, 3, 8, 15, 'reps', 60, 'Letakkan kedua tangan di tepi kursi atau bangku kokoh di belakang punggung, kaki lurus atau sedikit ditekuk. Turunkan pinggul hingga siku sekitar 90 derajat lalu dorong naik.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6a3adae0-ed83-4c5c-a0f2-fdeb5f04c96a', 'EX145', 'Bodyweight tricep extension (floor)', 'horizontal_push', 'triceps', 'bodyweight', 2, 33, 3, 8, 12, 'reps', 60, 'Dari posisi plank lutut atau ujung kaki dengan tangan agak di depan bahu, turunkan siku menyentuh lantai lalu dorong kembali lurus menggunakan trisep.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('3fd48bc2-4501-4b34-b903-9a011b3e8226', 'EX146', 'Close-grip knee push-up', 'horizontal_push', 'triceps', 'bodyweight', 1, 34, 3, 10, 15, 'reps', 60, 'Posisi push-up bertumpu lutut dengan tangan selebar bahu dan siku rapat ke rusuk. Turunkan dada lalu dorong naik fokus pada otot trisep.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('3c508674-0b94-451c-afef-a49dae2f3ba9', 'EX147', 'Isometric towel bicep curl', 'horizontal_pull', 'biceps', 'bodyweight', 1, 35, 3, 10, 15, 'reps', 45, 'Injak bagian tengah handuk kokoh dengan satu kaki, pegang kedua ujungnya. Tarik ke atas sekuat tenaga melawan tahanan kaki seperti gerakan curl secara terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('98394128-9e52-4770-aae8-8153477a990c', 'EX148', 'Cable crunch', 'core', 'core', 'gym', 1, 10, 3, 12, 15, 'reps', 60, 'Berlutut di depan puli atas sambil memegang tali rope di samping kepala. Tekuk tulang belakang ke bawah mengarah ke lutut menggunakan otot perut bukan pinggul.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('651fc9b7-0af8-4ea0-9d12-bc4218ba22c7', 'EX149', 'Hanging leg raise', 'core', 'core', 'gym', 2, 11, 3, 8, 15, 'reps', 75, 'Bergantung di palang pull-up dengan tubuh stabil tanpa berayun. Angkat kedua kaki lurus ke depan setinggi pinggul atau lebih tinggi lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('d909cb1a-fa22-4008-b3ed-4dcc5e2a6d80', 'EX150', 'Hanging knee raise', 'core', 'core', 'gym', 1, 12, 3, 10, 15, 'reps', 60, 'Bergantung di palang atau captain''s chair, tarik kedua lutut ke arah dada dengan menggulung panggul sedikit ke atas lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5bff84a8-8067-4b39-a837-e1a42f692959', 'EX151', 'Cable woodchopper', 'core', 'core', 'gym', 1, 13, 3, 10, 15, 'reps', 60, 'Berdiri menyamping dari puli tinggi atau tengah, pegang handel dengan kedua tangan. Putar batang tubuh menarik kabel diagonal melintasi tubuh untuk melatih otot oblique.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('26e2f41c-3315-4dd0-bf19-0713505fd547', 'EX152', 'Cable Pallof press', 'core', 'core', 'gym', 1, 14, 3, 10, 12, 'reps', 60, 'Berdiri menyamping dari puli setinggi dada, pegang handel di depan dada. Dorong lurus ke depan sambil menahan gaya tarik kabel agar tubuh tidak berputar.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('46c15a76-6332-4b61-90c7-2ceb6ad53dd2', 'EX153', 'Ab crunch machine', 'core', 'core', 'gym', 1, 15, 3, 12, 15, 'reps', 60, 'Duduk di mesin crunch dengan punggung menempel bantalan. Tekuk tubuh ke depan dengan mengontraksikan otot perut lalu kembali perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('a2652e2c-3259-4b79-ac37-866e43e3a584', 'EX154', 'Decline bench sit-up', 'core', 'core', 'gym', 2, 16, 3, 10, 15, 'reps', 60, 'Kunci kaki di decline bench, silangkan tangan di dada. Turunkan punggung terkontrol lalu angkat kembali menggunakan otot perut tanpa menarik leher.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('56c6a49e-1325-4f92-8040-e729d09904d3', 'EX155', 'Ab wheel rollout', 'core', 'core', 'gym', 2, 17, 3, 6, 12, 'reps', 75, 'Berlutut di matras sambil memegang ab wheel di depan bahu. Gelindingkan roda ke depan sejauh punggung bawah tetap netral lalu tarik kembali menggunakan perut.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('14f8fa4d-960f-4380-891d-95900f173fe3', 'EX156', 'Dumbbell Russian twist', 'core', 'core', 'dumbbell', 1, 18, 3, 12, 20, 'reps', 45, 'Duduk dengan lutut ditekuk dan punggung condong 45 derajat sambil memegang satu dumbbell. Putar batang tubuh ke kanan dan kiri secara terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('de60795d-58f1-4b84-9946-5cc98ac6872e', 'EX157', 'Dumbbell side bend', 'core', 'core', 'dumbbell', 1, 19, 3, 12, 15, 'reps', 45, 'Berdiri tegak memegang satu dumbbell di tangan kanan. Miringkan tubuh sedikit ke kanan lalu tarik kembali tegak menggunakan otot perut samping kiri, kemudian ganti sisi.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('1efc59f3-5631-40bb-96f9-5ea0dcf12be5', 'EX158', 'Dumbbell suitcase carry', 'carry', 'core', 'dumbbell', 1, 20, 3, 20, 40, 'seconds', 60, 'Pegang satu dumbbell berat di satu tangan saja, jaga bahu dan pinggul tetap sejajar tanpa miring. Berjalan stabil selama durasi set lalu ganti sisi.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('0febb8ca-907f-4ccd-8075-6091605738d4', 'EX159', 'Crunch', 'core', 'core', 'bodyweight', 1, 21, 3, 12, 20, 'reps', 45, 'Berbaring telentang dengan lutut ditekuk, tangan ringan di samping kepala atau dada. Angkat bahu dari matras dengan mengontraksikan perut lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('4bf9ece6-829e-4cd0-ac4c-c85d9635485d', 'EX160', 'Bicycle crunch', 'core', 'core', 'bodyweight', 1, 22, 3, 16, 24, 'reps', 45, 'Berbaring telentang, angkat bahu dan kaki. Pertemukan siku kanan ke lutut kiri sambil meluruskan kaki kanan secara bergantian dengan ritme terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('ce1b03a3-208a-4faf-b5c4-03bdf906c583', 'EX161', 'Lying leg raise', 'core', 'core', 'bodyweight', 2, 23, 3, 10, 15, 'reps', 60, 'Berbaring telentang dengan punggung bawah menempel lantai dan tangan di samping pinggul. Angkat kedua kaki lurus ke atas 90 derajat lalu turunkan perlahan tanpa menyentuh lantai.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('c0492015-96d0-469c-b34a-f5047952c4ea', 'EX162', 'Reverse crunch', 'core', 'core', 'bodyweight', 1, 24, 3, 12, 15, 'reps', 45, 'Berbaring telentang dengan lutut ditekuk 90 derajat. Tarik lutut ke dada hingga pinggul sedikit terangkat dari lantai lalu turunkan perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('b82b48d9-76e8-4726-b689-d6ee2f630485', 'EX163', 'Flutter kicks', 'core', 'core', 'bodyweight', 1, 25, 3, 20, 40, 'seconds', 45, 'Berbaring telentang, kencangkan perut agar pinggang menempel lantai. Angkat kedua kaki lurus sedikit dari lantai lalu ayunkan naik-turun bergantian cepat dan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('bb59fad3-32ac-44dc-bae3-59011ce47a7b', 'EX164', 'Hollow body hold', 'core', 'core', 'bodyweight', 2, 26, 3, 20, 40, 'seconds', 60, 'Berbaring telentang, tekan punggung bawah kuat ke lantai, angkat bahu, lengan ke belakang, dan kaki lurus sedikit dari lantai membentuk kurva cekung.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('892823f9-6dab-4cb7-a821-2a0354acc658', 'EX165', 'Mountain climber', 'core', 'core', 'bodyweight', 1, 27, 3, 20, 40, 'seconds', 45, 'Dari posisi high plank, tarik lutut kanan dan kiri ke arah dada secara bergantian dengan cepat sambil menjaga pinggul sejajar.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('c02f0ceb-0852-4d17-be35-5f28026a405c', 'EX166', 'Russian twist (bodyweight)', 'core', 'core', 'bodyweight', 1, 28, 3, 16, 24, 'reps', 45, 'Duduk dengan lutut ditekuk dan badan sedikit condong ke belakang. Putar bahu ke kanan dan kiri menyentuhkan tangan di samping pinggul.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('afb79abc-dc70-41fb-87c6-4131a6d0ea12', 'EX167', 'Bird dog', 'core', 'core', 'bodyweight', 1, 29, 3, 10, 14, 'reps', 45, 'Posisi merangkak dengan punggung rata. Luruskan lengan kanan ke depan dan kaki kiri ke belakang bersamaan, tahan 2 detik, kembali, lalu bergantian sisi.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('211482e0-0789-48eb-8c6c-5634aa88c056', 'EX168', 'V-Up', 'core', 'core', 'bodyweight', 2, 30, 3, 8, 15, 'reps', 60, 'Berbaring telentang lurus dengan lengan di atas kepala. Angkat tubuh bagian atas dan kedua kaki lurus bersamaan hingga tangan menyentuh ujung kaki membentuk huruf V.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('c05709e4-ffd6-4583-a2f6-9460aa85ff70', 'EX169', 'Heel touch', 'core', 'core', 'bodyweight', 1, 31, 3, 16, 24, 'reps', 45, 'Berbaring telentang dengan lutut ditekuk dan bahu sedikit terangkat. Condongkan badan menyentuh tumit kanan dan kiri bergantian untuk melatih oblique.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5685d1cd-3630-47b7-bb52-dcdb4c3aa62c', 'EX170', 'Sit-up', 'core', 'core', 'bodyweight', 1, 32, 3, 10, 20, 'reps', 45, 'Berbaring telentang dengan lutut ditekuk dan telapak kaki menapak lantai. Angkat tubuh hingga duduk tegak menggunakan perut lalu turunkan kembali perlahan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9c4f9ce2-66e8-4faa-af74-46c7a8396a7f', 'EX171', 'Treadmill incline walk', 'carry', 'cardio', 'gym', 1, 15, 3, 60, 120, 'seconds', 45, 'Atur treadmill pada tanjakan 6–12% dengan kecepatan jalan cepat 4–5,5 km/jam. Berjalan tegak tanpa bertumpu berat pada pegangan untuk kardio rendah benturan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('cdb33e6c-ee1c-4319-8ff8-ad211debdb48', 'EX172', 'Treadmill jogging / running', 'carry', 'cardio', 'gym', 1, 16, 3, 60, 120, 'seconds', 60, 'Lari atau joging ringan dengan kecepatan nyaman di treadmill. Jaga postur tegak, ayunan lengan rileks, dan pendaratan kaki ringan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('ed61e726-e8e3-4320-8c19-787bc88a6a12', 'EX173', 'Stationary bike', 'carry', 'cardio', 'gym', 1, 17, 3, 60, 120, 'seconds', 45, 'Atur tinggi sadel agar lutut sedikit menekuk saat pedal di bawah. Kayuh dengan resistensi sedang hingga tinggi untuk melatih daya tahan jantung dan kaki.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('d9a9ec2b-f400-43ae-b673-c0b05a3bbb03', 'EX174', 'Rowing machine', 'carry', 'cardio', 'gym', 1, 18, 3, 60, 120, 'seconds', 60, 'Duduk di mesin ergometer, dorong kuat melalui kaki terlebih dahulu, condongkan tubuh sedikit ke belakang, lalu tarik pegangan ke dada bawah secara berirama.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('c9c11f4f-e317-48d4-ad91-59969d6ac557', 'EX175', 'Elliptical trainer', 'carry', 'cardio', 'gym', 1, 19, 3, 60, 120, 'seconds', 45, 'Berdiri di pedal elips dan pegang handel bergerak. Kayuh dengan ritme stabil untuk latihan kardio seluruh tubuh yang ramah sendi.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5db2ee7e-2583-43bd-93ca-e96602a69864', 'EX176', 'Stair climber', 'carry', 'cardio', 'gym', 2, 20, 3, 60, 120, 'seconds', 60, 'Naiki anak tangga mesin dengan ritme konsisten dan postur tegak. Hindari membungkuk berlebihan pada pegangan untuk melatih glutes dan stamina.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6b1b9ef5-b8e2-49f9-b2dd-cc5e262e706a', 'EX177', 'Battle ropes', 'carry', 'full_body', 'gym', 2, 21, 3, 20, 40, 'seconds', 60, 'Berdiri posisi setengah squat memegang ujung tali tebal. Ayunkan lengan naik-turun bergantian cepat menciptakan gelombang konsisten hingga ujung tali.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('1b5ae14b-adec-4481-9ba3-bea09e187bd6', 'EX178', 'Sled push', 'carry', 'full_body', 'gym', 2, 22, 3, 20, 40, 'seconds', 90, 'Condongkan tubuh ke depan dengan lengan lurus mendorong tiang sled. Langkahkan kaki kuat dan stabil sepanjang lintasan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('6c398e76-e1a0-4e15-9010-8b6d1f5b4e97', 'EX179', 'Dumbbell thruster', 'squat', 'full_body', 'dumbbell', 2, 25, 3, 8, 12, 'reps', 90, 'Pegang dumbbell di bahu, turun ke posisi squat penuh. Dorong berdiri eksplosif dan lanjutkan menekan dumbbell lurus ke atas kepala dalam satu gerakan mulus.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('31b299ee-7977-4acf-97b2-27704c18587c', 'EX180', 'Dumbbell clean and press', 'vertical_push', 'full_body', 'dumbbell', 2, 26, 3, 6, 10, 'reps', 90, 'Mulai dengan dumbbell di samping paha, dorong pinggul mengangkat dumbbell ke bahu (clean) lalu tekan lurus ke atas kepala dan turunkan terkontrol.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('15e49e08-f0e5-44bb-af84-10782ba978bc', 'EX181', 'Dumbbell swing', 'hinge', 'full_body', 'dumbbell', 1, 27, 3, 12, 20, 'reps', 60, 'Pegang satu dumbbell dengan kedua tangan di antara kaki. Engselkan pinggul ke belakang lalu dorong pinggul maju kuat untuk mengayunkan dumbbell setinggi dada.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('389b4b93-7740-424b-9251-9051a4295b0b', 'EX182', 'Burpee', 'carry', 'full_body', 'bodyweight', 2, 30, 3, 8, 15, 'reps', 75, 'Dari berdiri, turun ke squat, letakkan tangan di lantai, lompatkan kaki ke plank, lakukan push-up opsional, lompat kembali ke squat lalu lompat ke atas.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('26202f69-fbba-45a9-93cb-837256c05928', 'EX183', 'Jumping jacks', 'carry', 'cardio', 'bodyweight', 1, 31, 3, 30, 60, 'seconds', 45, 'Berdiri rapat lalu lompat membuka kaki melebar sambil mengangkat kedua tangan di atas kepala. Kembali ke posisi awal dengan ritme cepat dan stabil.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('b03cc4c4-1e22-49b4-a680-482a9c445395', 'EX184', 'High knees', 'carry', 'cardio', 'bodyweight', 1, 32, 3, 20, 45, 'seconds', 45, 'Berlari di tempat sambil mengangkat lutut setinggi pinggul secara bergantian cepat dan mengayunkan lengan aktif.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('ddffeb53-97fc-4fee-b81d-2521793568bf', 'EX185', 'Butt kicks', 'carry', 'cardio', 'bodyweight', 1, 33, 3, 20, 45, 'seconds', 45, 'Berlari di tempat sambil menendangkan tumit ke arah bokong secara bergantian untuk pemanasan dan kardio ringan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5e963a22-8230-49a0-a36c-8f087acc2188', 'EX186', 'Skater jumps', 'carry', 'cardio', 'bodyweight', 2, 34, 3, 20, 45, 'seconds', 60, 'Melompat menyamping dari kaki kanan ke kaki kiri seperti pemain seluncur es, mendarat lembut dengan satu kaki sambil menyilangkan kaki lainnya di belakang.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('5199c5c2-49dc-4fbb-9f50-f9a0e1f13172', 'EX187', 'Shadowboxing', 'carry', 'cardio', 'bodyweight', 1, 35, 3, 30, 60, 'seconds', 45, 'Berdiri dalam kuda-kuda tinju, lontarkan kombinasi pukulan jab, cross, hook, dan uppercut ke udara dengan gerak kaki ringan untuk kardio intens.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('383ddf6e-bfc1-4bb5-a4d5-01c187c23c44', 'EX188', 'Inchworm walkout', 'carry', 'full_body', 'bodyweight', 1, 36, 3, 8, 12, 'reps', 60, 'Dari berdiri, bungkuk menyentuh lantai, jalankan kedua tangan maju hingga posisi plank penuh, tahan 1 detik, lalu jalankan tangan kembali ke kaki dan berdiri.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('d5ca8f43-c723-4743-8b0e-4357e647bb46', 'EX189', 'Bear crawl', 'carry', 'full_body', 'bodyweight', 2, 37, 3, 20, 40, 'seconds', 60, 'Posisi merangkak dengan lutut melayang 3 cm di atas lantai. Berjalan maju dan mundur dengan tangan dan kaki berlawanan sambil menjaga punggung datar.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('933a3815-c003-4ed9-b42b-5192cef9c051', 'EX190', 'Jump rope / skipping', 'carry', 'cardio', 'bodyweight', 1, 38, 3, 30, 60, 'seconds', 45, 'Lompat ringan dengan ujung kaki sambil memutar tali skipping melalui pergelangan tangan. Jika tanpa tali, lakukan simulasi lompat tali dengan ritme konstan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T21:48:12.222239', '2026-11-19T21:48:12.222239') ON CONFLICT DO NOTHING;
